2. Write a PL/SQL block to accept product name, qty and price from user and then calculate discount in Rs. based on the given (%).

/*
Write a PL/SQL block to accept product name, qty and price
from user and then calculate discount in Rs. based on the given (%).
*/

SET SERVEROUTPUT ON
SET FEEDBACK OFF
SET VERIFY OFF

DECLARE
PNAME           VARCHAR2(30);
QTY             NUMBER(5);
PRICE           NUMBER(10,2);
DISCOUNT_PCT    NUMBER(5,2);
TOTAL_AMT       NUMBER(10,2);
DISCOUNT_AMT    NUMBER(10,2);
NET_AMT         NUMBER(10,2);

BEGIN

PNAME := '&Product_Name';
QTY := &Quantity;
PRICE := &Price;
DISCOUNT_PCT := &Discount_Percentage;

TOTAL_AMT := QTY * PRICE;

DISCOUNT_AMT := (TOTAL_AMT * DISCOUNT_PCT) / 100;
