DBMS_OUTPUT.PUT_LINE('=========================================');
DBMS_OUTPUT.PUT_LINE('          PRODUCT BILL DETAILS');
DBMS_OUTPUT.PUT_LINE('=========================================');
DBMS_OUTPUT.PUT_LINE('Product Name    : ' || PNAME);
DBMS_OUTPUT.PUT_LINE('Quantity        : ' || QTY);
DBMS_OUTPUT.PUT_LINE('Price per unit  : ' || PRICE);
DBMS_OUTPUT.PUT_LINE('Discount (%)    : ' || DISCOUNT_PCT || '%');
DBMS_OUTPUT.PUT_LINE('                ');
DBMS_OUTPUT.PUT_LINE('Total Amount    : ' || TOTAL_AMT);
DBMS_OUTPUT.PUT_LINE('Discount Amount : ' || DISCOUNT_AMT);
DBMS_OUTPUT.PUT_LINE('Net Amount      : ' || NET_AMT);
DBMS_OUTPUT.PUT_LINE('=========================================');

END;
/

