3. Write a PL/SQL block which displays gross salary of employees as per user input EID. (Consider EMP table with EID, EName, Deptno, Deptname Gender, Age, BasicSal) with appropriate data types.) Gross_Salary: BASICSAL + (DA + HRA + Medical) -- PF. Rules: HRA = 15% of basic, DA = 50% of basic, Medical = Rs. 500, PF = 10% of basic.

/*
Write a PL/SQL block which displays gross salary of employees as per user input EID.

Gross Salary = BASIC SAL + DA + HRA + Medical - PF

Rules:
HRA     = 15% of Basic Salary
DA      = 50% of Basic Salary
Medical = Rs. 500
PF      = 10% of Basic Salary
*/

SET SERVEROUTPUT ON
SET FEEDBACK OFF
SET VERIFY OFF

DECLARE
V_EID       EMP.EID%TYPE;
V_ENAME     EMP.ENAME%TYPE;
V_DEPTNO    EMP.DEPTNO%TYPE;
V_DEPTNAME  EMP.DEPTNAME%TYPE;
V_GENDER    EMP.GENDER%TYPE;
V_AGE       EMP.AGE%TYPE;
V_BASICSAL  EMP.BASICSAL%TYPE;

V_HRA       NUMBER(10,2);
V_DA        NUMBER(10,2);
V_MEDICAL   CONSTANT NUMBER(10,2) := 500;
V_PF        NUMBER(10,2);
V_GROSS_SAL NUMBER(10,2);

BEGIN

V_EID := &Enter_Employee_ID;

SELECT EID, ENAME, DEPTNO, DEPTNAME, GENDER, AGE, BASICSAL
INTO V_EID, V_ENAME, V_DEPTNO, V_DEPTNAME, V_GENDER, V_AGE, V_BASICSAL
FROM EMP
WHERE EID = V_EID;

V_HRA := V_BASICSAL * 15 / 100;
V_DA := V_BASICSAL * 50 / 100;
V_PF := V_BASICSAL * 10 / 100;

V_GROSS_SAL := V_BASICSAL + V_HRA + V_DA + V_MEDICAL - V_PF;

DBMS_OUTPUT.PUT_LINE('=========================================');
DBMS_OUTPUT.PUT_LINE('        EMPLOYEE SALARY DETAILS');
DBMS_OUTPUT.PUT_LINE('=========================================');
DBMS_OUTPUT.PUT_LINE('Employee ID : ' || V_EID);
DBMS_OUTPUT.PUT_LINE('Name        : ' || V_ENAME);
DBMS_OUTPUT.PUT_LINE('Department No : ' || V_DEPTNO);
DBMS_OUTPUT.PUT_LINE('Department Name : ' || V_DEPTNAME);
DBMS_OUTPUT.PUT_LINE('Gender      : ' || V_GENDER);
DBMS_OUTPUT.PUT_LINE('Age         : ' || V_AGE);
DBMS_OUTPUT.PUT_LINE('-----------------------------------------');
DBMS_OUTPUT.PUT_LINE('Basic Salary : ' || V_BASICSAL);
DBMS_OUTPUT.PUT_LINE('HRA (15%)    : ' || V_HRA);
DBMS_OUTPUT.PUT_LINE('DA (50%)     : ' || V_DA);
DBMS_OUTPUT.PUT_LINE('Medical      : ' || V_MEDICAL);
DBMS_OUTPUT.PUT_LINE('PF (10%)     : ' || V_PF);
DBMS_OUTPUT.PUT_LINE('-----------------------------------------');
DBMS_OUTPUT.PUT_LINE('Gross Salary : ' || V_GROSS_SAL);
DBMS_OUTPUT.PUT_LINE('=========================================');

EXCEPTION
WHEN NO_DATA_FOUND THEN
DBMS_OUTPUT.PUT_LINE('Employee with EID ' || V_EID || ' not found!');
WHEN OTHERS THEN
DBMS_OUTPUT.PUT_LINE('Error: ' || SQLERRM);

END;
/

SET SERVEROUTPUT OFF
SET FEEDBACK ON
SET VERIFY ON

