8. Write a PL/SQL block to delete the record of employee for given EID.

/*
Write a PL/SQL block to delete the record of employee for given EID.
*/

SET SERVEROUTPUT ON
SET FEEDBACK OFF
SET VERIFY OFF

DECLARE
V_EID   EMP.EID%TYPE;
V_COUNT NUMBER;

BEGIN

V_EID := &Enter_Employee_ID_to_Delete;

SELECT COUNT(*) INTO V_COUNT
FROM EMP
WHERE EID = V_EID;

IF V_COUNT = 0 THEN
DBMS_OUTPUT.PUT_LINE('=========================================');
DBMS_OUTPUT.PUT_LINE('Employee with EID '||V_EID||' does not exist!');
DBMS_OUTPUT.PUT_LINE('=========================================');
ELSE
DELETE FROM EMP WHERE EID = V_EID;

DBMS_OUTPUT.PUT_LINE('=========================================');
DBMS_OUTPUT.PUT_LINE('        EMPLOYEE DELETION STATUS');
DBMS_OUTPUT.PUT_LINE('=========================================');
DBMS_OUTPUT.PUT_LINE('Employee with EID '||V_EID||' deleted successfully!');
DBMS_OUTPUT.PUT_LINE('Number of rows deleted: '||SQL%ROWCOUNT);
DBMS_OUTPUT.PUT_LINE('=========================================');

COMMIT;
END IF;

EXCEPTION
WHEN OTHERS THEN
DBMS_OUTPUT.PUT_LINE('Error: '||SQLERRM);
ROLLBACK;

END;
/

